INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 16, 'theory', 'Quiz: Non-Blocking I/O, epoll, io_uring, and Terminals');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 0, 'What does the EAGAIN error mean when reading from a non-blocking descriptor?', '["There is no data yet, so the call should be retried later: this is not a failure", "The descriptor is closed", "Not enough permissions", "The buffer is too small"]', 0, 'Non-blocking mode returns control immediately. EAGAIN (or EWOULDBLOCK) is the ordinary “come back later” answer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 1, 'Why is select considered outdated for thousands of connections?', '["It cannot wait on sockets", "It blocks all signals", "It is limited to numbers below 1024, takes the mask anew on every call, and scans all descriptors", "It works only on files"]', 2, 'poll removes the limit on numbers, but it also copies and scans the whole list.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 2, 'What makes epoll better than poll with 10,000 connections, of which two are active?', '["epoll works without the kernel", "Interests are stored in the kernel, and epoll_wait returns only the ready ones: the cost depends on the number of events", "epoll uses several threads by default", "epoll does not support sockets"]', 1, 'poll walks everything again. With epoll, ready descriptors land in a separate list, so waiting does not depend on the number of quiet connections.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 3, 'What must you do in EPOLLET mode after a notification?', '["Read exactly once", "Close the descriptor", "Re-register the descriptor with epoll_ctl", "Read until EAGAIN, otherwise the remainder will not trigger a new notification"]', 3, 'Edge-triggered mode reports a change of state. Unread data stays in the buffer, but there will be no new notifications.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 4, 'Why does epoll not help when reading an ordinary file on disk?', '["Files do not support descriptors", "epoll works only over the network", "A file on disk is always considered “ready”, yet read may still wait for the disk", "Files are always read instantly from the cache"]', 2, 'That is why servers move disk operations into a thread pool or use asynchronous interfaces such as io_uring.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 5, 'What does io_uring provide?', '["Two rings in shared memory: many operations per system call, and in polling mode no calls at all", "A replacement for the file system", "Encryption of network traffic", "Running programs without a process"]', 0, 'The program puts requests into the submission ring, and the kernel puts results into the completion ring.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 6, 'What happens when you press Ctrl-C in a terminal?', '["The shell always exits", "The kernel restarts the terminal", "The program receives a character with code 3 and decides for itself", "The terminal driver (line discipline) sends SIGINT to the foreground process group"]', 3, 'In canonical mode the terminal itself turns control characters into signals. In raw mode the program receives the character.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 16, 7, 'What is a pseudoterminal (pty) for?', '["Encrypting keyboard input", "A master and slave pair: a terminal emulator or sshd drives a program that believes it is talking to a real terminal", "Sharing the screen between users", "Running programs without a shell"]', 1, 'The slave looks like an ordinary terminal, while the master is held by an emulator, an SSH server, or tmux.');
